// NanoHubSettingsCreateBulk is the builder for creating many NanoHubSettings entities in bulk.
type NanoHubSettingsCreateBulk struct {
	config
	err      error
	builders []*NanoHubSettingsCreate
	conflict []sql.ConflictOption
}

// Save creates the NanoHubSettings entities in the database.
func (nhscb *NanoHubSettingsCreateBulk) Save(ctx context.Context) ([]*NanoHubSettings, error) {
	if nhscb.err != nil {
		return nil, nhscb.err
	}
	specs := make([]*sqlgraph.CreateSpec, len(nhscb.builders))
	nodes := make([]*NanoHubSettings, len(nhscb.builders))
	mutators := make([]Mutator, len(nhscb.builders))
	for i := range nhscb.builders {
		func(i int, root context.Context) {
			builder := nhscb.builders[i]
			builder.defaults()
			var mut Mutator = MutateFunc(func(ctx context.Context, m Mutation) (Value, error) {
				mutation, ok := m.(*NanoHubSettingsMutation)
				if !ok {
					return nil, fmt.Errorf("unexpected mutation type %T", m)
				}
				if err := builder.check(); err != nil {
					return nil, err
				}
				builder.mutation = mutation
				var err error
				nodes[i], specs[i] = builder.createSpec()
				if i < len(mutators)-1 {
					_, err = mutators[i+1].Mutate(root, nhscb.builders[i+1].mutation)
				} else {
					spec := &sqlgraph.BatchCreateSpec{Nodes: specs}
					spec.OnConflict = nhscb.conflict
					// Invoke the actual operation on the latest mutation in the chain.
					if err = sqlgraph.BatchCreate(ctx, nhscb.driver, spec); err != nil {
						if sqlgraph.IsConstraintError(err) {
							err = &ConstraintError{msg: err.Error(), wrap: err}
						}
					}
				}
				if err != nil {
					return nil, err
				}
				mutation.id = &nodes[i].ID
				if specs[i].ID.Value != nil {
					id := specs[i].ID.Value.(int64)
					nodes[i].ID = int(id)
				}
				mutation.done = true
				return nodes[i], nil
			})
			for i := len(builder.hooks) - 1; i >= 0; i-- {
				mut = builder.hooks[i](mut)
			}
			mutators[i] = mut
		}(i, ctx)
	}
	if len(mutators) > 0 {
		if _, err := mutators[0].Mutate(ctx, nhscb.builders[0].mutation); err != nil {
			return nil, err
		}
	}
	return nodes, nil
}

